// ====== À REMPLIR UNE FOIS ======
const CONFIG = {
  MODE_TEST: true,                          // true = 3 mails seulement, tous vers ADRESSE_TEST, avec [TEST] dans l'objet
  ADRESSE_TEST: 'contact@nourmeet.com',
  TELEGRAM_CHAT_ID: '6339897621',           // reçoit le bilan quotidien (via @userinfobot)
  EXPEDITEUR: 'Nūr Meet <contact@nourmeet.com>',
  SIGNATAIRE: 'Walid',
  LIEN_CANDIDATURE: 'https://nourmeet.com/restaurateurs',
  SITE_WEB: 'https://nourmeet.com',         // lien du logo en bas du mail
  LOGO_URL: 'https://n8n.nourmeet.com/webhook/logo-nour-meet', // logo servi par le workflow 5 (vide = lien texte seul)
  PROPOSITIONS_PAR_JOUR: 50,
  RELANCE_1_APRES_JOURS: 4,                 // J+4 (validé le 26/09)
  RELANCE_2_APRES_JOURS: 9,                 // J+9 (validé le 26/09)
  PAUSE_ENTRE_MAILS_S: 45,                  // espacement des envois (délivrabilité)
  SUIVI_URL: 'https://n8n.nourmeet.com/webhook/ouverture', // pixel d'ouverture (workflow 7)
};

// Zones d'Île-de-France parcourues à tour de rôle
const ZONES = [
  'Paris 1er','Paris 2e','Paris 3e','Paris 4e','Paris 5e','Paris 6e','Paris 7e','Paris 8e','Paris 9e','Paris 10e',
  'Paris 11e','Paris 12e','Paris 13e','Paris 14e','Paris 15e','Paris 16e','Paris 17e','Paris 18e','Paris 19e','Paris 20e',
  'Neuilly-sur-Seine','Levallois-Perret','Boulogne-Billancourt','Issy-les-Moulineaux','Malakoff','Montrouge',
  'Saint-Denis','Saint-Ouen','Aubervilliers','Montreuil','Vincennes','Saint-Mandé','Créteil','Vitry-sur-Seine',
  'Ivry-sur-Seine','Nanterre','Courbevoie','Puteaux','Rueil-Malmaison','Versailles','Saint-Germain-en-Laye',
  'Argenteuil','Cergy','Sarcelles','Bobigny','Pantin','Clichy','Massy','Évry-Courcouronnes','Meaux',
];
const THEMES = [
  'restaurant halal haut de gamme',
  'restaurant sans alcool chic',
  'restaurant privatisable pour soirée',
  'restaurant lounge chicha',
  'restaurant gastronomique halal',
];
// 10 requêtes par jour : 2 zones x 5 thèmes, qui tournent chaque jour
const jour = Math.floor(Date.now() / 86400000);
const items = [];
for (let z = 0; z < 2; z++) {
  const zone = ZONES[(jour * 2 + z) % ZONES.length];
  for (const theme of THEMES) items.push({ json: { ...CONFIG, textQuery: `${theme} ${zone}`, zone } });
}
return items;

const PRIX = { PRICE_LEVEL_INEXPENSIVE: '€', PRICE_LEVEL_MODERATE: '€€', PRICE_LEVEL_EXPENSIVE: '€€€', PRICE_LEVEL_VERY_EXPENSIVE: '€€€€' };
const vus = new Set(); const out = [];
for (const it of $input.all()) {
  for (const p of (it.json.places || [])) {
    if (!p.id || vus.has(p.id)) continue;
    if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
    const adr = p.formattedAddress || '';
    const cp = (adr.match(/\b(75|77|78|91|92|93|94|95)\d{3}\b/) || [])[0];
    if (!cp) continue;                                   // hors Île-de-France
    vus.add(p.id);
    const ville = (adr.match(new RegExp(cp + '\\s+([^,]+)')) || [])[1] || '';
    const indices = [];
    if (p.goodForGroups) indices.push('adapté aux groupes (Google)');
    if (p.reservable) indices.push('réservable (Google)');
    if (p.servesBeer || p.servesWine) indices.push('sert de l\'alcool (Google)');
    if (p.servesCocktails) indices.push('cocktails (Google)');
    out.push({ json: {
      place_id: p.id, nom: p.displayName?.text || '', adresse: adr, ville: ville.trim(), code_postal: cp,
      site: p.websiteUri || '', telephone: p.nationalPhoneNumber || '', maps_url: p.googleMapsUri || '',
      note: p.rating ?? null, nb_avis: p.userRatingCount ?? null, niveau_prix: PRIX[p.priceLevel] || '',
      groupes: !!p.goodForGroups, alcool_google: !!(p.servesBeer || p.servesWine),
      indices_google: indices.join(', '),
    }});
  }
}
return out;

const texte = (html) => String(html || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/\s+/g, ' ');
const EXCLUS = /(example|exemple|domain|sentry|wixpress|wix\.com|godaddy|\.png|\.jpg|\.jpeg|\.gif|\.webp|\.svg|noreply|no-reply|privacy|rgpd@|dpo@)/i;
function emails(html) {
  const brut = String(html || '').replace(/&#64;|\[at\]|\(at\)/gi, '@');
  const trouves = brut.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
  return [...new Set(trouves.map(e => e.toLowerCase().replace(/^mailto:/, '')))].filter(e => !EXCLUS.test(e));
}
function indices(t) {
  const r = {};
  if (/\bhalal\b/i.test(t) && !/non[\s-]halal|pas halal/i.test(t)) r.halal = true;
  if (/sans alcool|mocktail|0\s?% alcool|alcohol[\s-]free/i.test(t)) r.sans_alcool = true;
  if (/privatis/i.test(t)) r.privatisation = true;
  if (/chicha|shisha|narguil/i.test(t)) r.chicha = true;
  const cap = t.match(/(?:jusqu['’]?\s?à|capacité(?: de)?|accueillir)\s*(\d{2,3})\s*(?:personnes|couverts|convives|invités|places)/i);
  if (cap) r.capacite = parseInt(cap[1], 10);
  return r;
}

const base = $('Au plus 120 sites à lire').all();
return $input.all().map((it, i) => {
  const p = base[i].json; const html = it.json.html || '';
  let contact_url = '';
  if (p.site) {
    const lien = (String(html).match(/href=["']([^"'#]*(?:contact|reserv|privatis|evenement|événement|groupe)[^"']*)["']/i) || [])[1];
    try { contact_url = new URL(lien || '/contact', p.site).href; } catch (e) { contact_url = ''; }
  }
  return { json: { ...p, emails_accueil: emails(html), indices_accueil: indices(texte(html)), contact_url } };
});

