function phraseAccroche(p) {
  const faits = [];
  if (p.sans_alcool === 'confirmé (site)') faits.push('votre offre de boissons sans alcool');
  if (p.privatisation === 'confirmé (site)') faits.push('la possibilité de privatiser vos espaces');
  const lieu = p.ville ? `${p.nom} à ${p.ville}` : p.nom;
  if (faits.length) return `En découvrant ${lieu}, et notamment ${faits.join(' et ')}, nous avons pensé que vous pourriez accueillir ce type de soirée.`;
  return `En découvrant ${lieu}, nous avons pensé que votre établissement pourrait accueillir ce type de soirée.`;
}
const PIED = (C) => `Bien cordialement,\n${C.SIGNATAIRE}\nNūr Meet\n${C.SITE_WEB}\n\nSi vous ne souhaitez plus recevoir de message de notre part, répondez simplement « STOP ».`;

function mailInitial(p, C) {
  return {
    objet: `${p.nom} : proposer vos soirées rencontre et networking sur Nūr Meet`,
    corps:
`Bonjour,

Je vous écris au nom de Nūr Meet, une plateforme qui publie des soirées de rencontre et de networking organisées dans des restaurants d'Île-de-France.

${phraseAccroche(p)}

Le principe est simple :
- vous proposez vos propres soirées payantes, de rencontre ou de networking, et publiez l'annonce sur Nūr Meet ;
- vous restez l'organisateur de la soirée dans votre établissement ;
- notre équipe valide chaque annonce avant sa publication.

Pour candidater, il suffit de créer votre compte ici : ${C.LIEN_CANDIDATURE}

Je reste disponible pour répondre à vos questions par simple retour de mail.

${PIED(C)}`,
  };
}

function mailRelance(p, n, C) {
  if (n === 1) return {
    objet: `Nūr Meet : vos soirées chez ${p.nom} ?`,
    corps:
`Bonjour,

Je me permets de revenir vers vous au sujet de Nūr Meet. Si l'idée d'organiser des soirées de rencontre ou de networking chez ${p.nom} vous intéresse, la candidature se fait en quelques minutes : ${C.LIEN_CANDIDATURE}

Nous validons chaque annonce avant publication, et vous restez l'organisateur de vos soirées.

${PIED(C)}`,
  };
  return {
    objet: `Dernier message : Nūr Meet et ${p.nom}`,
    corps:
`Bonjour,

Je vous adresse un dernier message au sujet de Nūr Meet. Si ce n'est pas le bon moment, aucun souci, je ne vous relancerai plus.

Si l'idée vous tente plus tard, vous pourrez toujours candidater ici : ${C.LIEN_CANDIDATURE}

${PIED(C)}`,
  };
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const C = $('Configuration et requêtes du jour').first().json;
const base = $("Analyser l'accueil").all();
const maintenant = new Date().toISOString();
return $input.all().map((it, i) => {
  const p = base[i].json; const html = it.json.html || '';
  const ic = indices(texte(html)); const ia = p.indices_accueil || {};
  const src = (k) => ia[k] ? p.site : (ic[k] ? p.contact_url : '');
  // e-mail : on préfère une adresse du domaine du site, puis contact@/reservation@
  const liste = [...new Set([...(p.emails_accueil || []), ...emails(html)])];
  let domaine = ''; try { domaine = new URL(p.site).hostname.replace(/^www\./, ''); } catch (e) {}
  const rang = (e) => (domaine && e.endsWith('@' + domaine) ? 0 : 2) + (/^(contact|info|reservation|resa|events?|bonjour|hello)@/.test(e) ? 0 : 1);
  liste.sort((a, b) => rang(a) - rang(b));
  const email = liste[0] || '';
  const email_source = email ? ((p.emails_accueil || []).includes(email) ? p.site : p.contact_url) : '';
  const etat = (k) => src(k) ? 'confirmé (site)' : 'à vérifier';
  const capa = ia.capacite || ic.capacite;
  const f = {
    ...p, email, email_source,
    halal: etat('halal'), sans_alcool: etat('sans_alcool'), privatisation: etat('privatisation'),
    chicha: src('chicha') ? 'oui (site)' : 'non mentionné',
    capacite: capa ? `${capa} (site : ${src('capacite')})` : 'à vérifier',
  };
  f.sources = ['halal', 'sans_alcool', 'privatisation', 'chicha', 'capacite']
    .filter(k => src(k)).map(k => `${k}: ${src(k)}`).join(' | ');
  // Score : priorité haut de gamme, halal, sans alcool, privatisation, 20 pers.
  let s = 0;
  if (f.niveau_prix === '€€€' || f.niveau_prix === '€€€€') s += 3; else if (f.niveau_prix === '€€') s += 1;
  if (f.halal.startsWith('confirmé')) s += 3;
  if (f.sans_alcool.startsWith('confirmé')) s += 2;
  if (f.privatisation.startsWith('confirmé')) s += 2;
  if (capa && capa >= 20) s += 2;
  if (p.groupes) s += 1;
  if ((p.note || 0) >= 4.3 && (p.nb_avis || 0) >= 50) s += 1;
  f.score = s;
  const m = mailInitial(f, C);
  f.objet = m.objet; f.corps = m.corps; f.date_decouverte = maintenant;
  const ok = (v) => v.startsWith('confirmé') || v.startsWith('oui');
  const confirmes = [['halal', f.halal], ['boissons sans alcool', f.sans_alcool], ['privatisation', f.privatisation], ['chicha', f.chicha]]
    .filter(([, v]) => ok(v)).map(([k]) => k);
  if (capa) confirmes.push(`capacité ${capa} pers.`);
  const averifier = [['halal', f.halal], ['boissons sans alcool', f.sans_alcool], ['privatisation', f.privatisation], ['capacité 20+', f.capacite]]
    .filter(([, v]) => v === 'à vérifier').map(([k]) => k);
  f.telegram_text =
`<b>🍽 ${esc(f.nom)}</b>  ·  score ${s}
📍 ${esc(f.adresse)}
🌐 ${esc(f.site || 'pas de site')}  ·  ⭐ ${f.note ?? '?'} (${f.nb_avis ?? 0} avis)  ·  ${esc(f.niveau_prix || 'prix ?')}
✉️ ${esc(email)}  <i>(trouvé sur ${esc(email_source)})</i>
✅ Confirmé : ${esc(confirmes.join(', ') || 'rien de confirmé')}
❓ À vérifier : ${esc(averifier.join(', ') || 'rien')}
ℹ️ Google : ${esc(f.indices_google || 'aucun indice')}
🔎 Sources : ${esc(f.sources || 'aucune')}
🗺 ${esc(f.maps_url)}

<b>Objet :</b> ${esc(f.objet)}
<blockquote expandable>${esc(f.corps)}</blockquote>`;
  delete f.emails_accueil; delete f.indices_accueil;
  return { json: f };
});

const c = ["place_id", "nom", "adresse", "ville", "code_postal", "site", "telephone", "maps_url", "email", "email_source", "note", "nb_avis", "niveau_prix", "halal", "sans_alcool", "privatisation", "capacite", "chicha", "indices_google", "sources", "score", "date_decouverte"];
const o = {}; for (const k of c) o[k] = $json[k] ?? null;
o.statut = 'sans_email'; o.nb_relances = 0;
return { json: o };

const C = $('Configuration et requêtes du jour').first().json;
const vus = new Set();
return $input.all().sort((a, b) => b.json.score - a.json.score)
  .filter(it => !vus.has(it.json.email) && vus.add(it.json.email))
  .slice(0, C.MODE_TEST ? 3 : C.PROPOSITIONS_PAR_JOUR);   // en mode test : 3 mails seulement

const c = ["place_id", "nom", "adresse", "ville", "code_postal", "site", "telephone", "maps_url", "email", "email_source", "note", "nb_avis", "niveau_prix", "halal", "sans_alcool", "privatisation", "capacite", "chicha", "indices_google", "sources", "score", "date_decouverte"];
const o = {}; for (const k of c) o[k] = $json[k] ?? null;
o.statut = 'propose'; o.nb_relances = 0;
return { json: o };

const src = $('Trier et garder les 50 meilleurs').all();
return $input.all().map((_, i) => { const p = src[i].json; return { json: {
  prospect_place_id: p.place_id, nom: p.nom, email: p.email, type: 'initial', objet: p.objet, corps: p.corps,
  statut: 'a_envoyer', date_proposition: new Date().toISOString(),
}}; });

const C = $('Configuration et requêtes du jour').first().json;

const e = $json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (t) => esc(t).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1">$1</a>').replace(/\n/g, '<br>');
// Le logo se place juste après la signature, avant la ligne « STOP »
const i = String(e.corps).lastIndexOf('\n\nSi vous ne souhaitez plus');
const avant = i >= 0 ? String(e.corps).slice(0, i) : String(e.corps);
const stop = i >= 0 ? String(e.corps).slice(i + 2) : '';
const site = esc(C.SITE_WEB);
const logo = C.LOGO_URL
  ? `<a href="${site}"><img src="${esc(C.LOGO_URL)}" alt="Nūr Meet" width="140" style="border:0;display:block;margin-top:16px"></a>`
  : '';
// Pixel d'ouverture : compté quand la messagerie affiche les images (approximatif)
const pixel = C.SUIVI_URL ? `<img src="${esc(C.SUIVI_URL)}?e=${e.envoi_id}" width="1" height="1" alt="" style="border:0">` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222">${fmt(avant)}${logo}${stop ? `<p style="font-size:12px;color:#777">${fmt(stop)}</p>` : ''}${pixel}</div>`;
return { json: { ...e, html,
  to: C.MODE_TEST ? C.ADRESSE_TEST : e.email,
  subject: (C.MODE_TEST ? '[TEST] ' : '') + e.objet,
  test: !!C.MODE_TEST } };

const e = $json;                      // ligne np_envois mise à jour
const now = new Date().toISOString();
if (e.statut === 'test') return { json: { statut: 'test' } };
const o = { date_dernier_envoi: now };
if (e.type === 'initial') Object.assign(o, { statut: 'contacte', date_premier_envoi: now, nb_relances: 0 });
if (e.type === 'relance1') Object.assign(o, { statut: 'relance1', nb_relances: 1 });
if (e.type === 'relance2') Object.assign(o, { statut: 'relance2', nb_relances: 2 });
return { json: o };
